import importlib.util,json,pathlib,sqlite3,tempfile,unittest
from unittest.mock import patch
spec=importlib.util.spec_from_file_location('live_watch_bridge',pathlib.Path(__file__).resolve().parents[1]/'scripts/live_watch_bridge.py');mod=importlib.util.module_from_spec(spec);spec.loader.exec_module(mod)
class ArtifactMirrorTests(unittest.TestCase):
 def test_artifacts_publish_only_python_boards_and_shared_state(self):
  db=sqlite3.connect(':memory:');db.row_factory=sqlite3.Row;db.executescript('''CREATE TABLE agent_tool_runs(id TEXT,event_id TEXT,owner_id TEXT,call_number INTEGER,name TEXT,arguments TEXT,result TEXT,status TEXT,created_at REAL);CREATE TABLE agent_boards(id TEXT,event_id TEXT,room_id TEXT,owner_id TEXT,message_id TEXT,body TEXT,created_at REAL);CREATE TABLE agent_workspaces(id TEXT,event_id TEXT,room_id TEXT,title TEXT);CREATE TABLE workspace_revisions(workspace_id TEXT,revision INTEGER,owner_id TEXT,body TEXT,status TEXT,message_id TEXT,created_at REAL);CREATE TABLE person_note_revisions(body TEXT);CREATE TABLE allowance_transfers(id TEXT,event_id TEXT,from_owner TEXT,to_owner TEXT,amount_usd INTEGER,reason TEXT,conversation_id TEXT,workspace_id TEXT,call_number INTEGER,created_at REAL);''')
  for identifier,event,name,arguments,result in [('code','e','python_run',{'code':'print(42)'},{'ok':True,'data':{'stdout':'42','result':42}}),('old','old','python_run',{'code':'OLD EVENT'},{'ok':True}),('note','e','person_note_read',{'peer_id':'b'},{'data':{'text':'PRIVATE NOTE'}}),('search','e','web_read',{'url':'PRIVATE URL'},{'data':'PRIVATE RESULT'})]:db.execute('INSERT INTO agent_tool_runs VALUES(?,?,?,?,?,?,?,?,?)',(identifier,event,'a',1,name,json.dumps(arguments),json.dumps(result),'completed',1))
  db.execute("INSERT INTO person_note_revisions VALUES('PRIVATE MEMORY')");db.execute('INSERT INTO agent_boards VALUES(?,?,?,?,?,?,?)',('b','e','room','a','m',json.dumps({'title':'Circle','text':'shared','equations':['x=1'],'shapes':[{'type':'circle','x':10,'y':20,'r':5}],'private':'PRIVATE'}),2));db.execute("INSERT INTO agent_workspaces VALUES('w','e','room','Music')");db.execute("INSERT INTO workspace_revisions VALUES('w',1,'a','Shared score','active','m',3)")
  db.execute("INSERT INTO allowance_transfers VALUES('t','e','a','b',2000000,'Continue the score','room','w',4,4)");db.execute("INSERT INTO allowance_transfers VALUES('old-t','old','a','b',2000000,'OLD EVENT',NULL,NULL,4,4)")
  result=mod.artifacts_from(db,'e',{'room'});self.assertEqual([r['kind'] for r in result],['python','board','workspace','transfer']);self.assertEqual(result[3]['data']['amount_usd'],2);self.assertEqual(result[3]['data']['recipient_id'],'b');self.assertNotIn('PRIVATE',json.dumps(result));self.assertNotIn('OLD EVENT',json.dumps(result));self.assertEqual(result[0]['data']['stdout'],'42');self.assertEqual(result[1]['data']['shapes'][0]['type'],'circle');self.assertEqual(result[2]['data']['state'],'Shared score')
 def test_incremental_mirroring_updates_running_code_without_republishing_unchanged_content(self):
  with tempfile.TemporaryDirectory() as tmp:
   root=pathlib.Path(tmp);config=root/'.data/live-residency';config.mkdir(parents=True);(config/'site-bridge.json').write_text(json.dumps({'origin':'https://example.test','token':'synthetic'}));mirror=mod.WatchMirror(root);requests=[]
   def request(payload):requests.append(payload);return {'last_seq':0} if payload['action']=='status' else {'saved':True}
   mirror.request=request;state={'event_id':'e'};artifact={'id':'code','data':{'status':'started'}}
   with patch.object(mod,'capture',return_value=(state,[],[artifact])):mirror.tick();mirror.tick()
   self.assertEqual(sum(bool(r.get('artifacts')) for r in requests),1)
   with patch.object(mod,'capture',return_value=(state,[],[{'id':'code','data':{'status':'completed'}}])):mirror.tick()
   self.assertEqual(sum(bool(r.get('artifacts')) for r in requests),2);self.assertEqual(json.loads(mirror.status_file.read_text())['model_calls'],0)
